Brief:
A paper kite rides the wind over the rooftops. Tap to rise, avoid the chimneys and collect ribbons while the wind slowly speeds up.

Plan:
{"gameType":"arcade-run","input":"tap-anywhere","lang":"en","loop":"Tap to make the paper kite rise on the wind, dodging rooftop chimneys and collecting ribbons as the breeze speeds up. Hitting a chimney ends the flight and shows your ribbon count.","slug":"kite-on-the-wind","style":"paper-cut","title":"Kite on the Wind"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="en">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Kite on the Wind</title>
7| <style>
8|   html, body {
9|     margin: 0;
10|     padding: 0;
11|     width: 100%;
12|     height: 100%;
13|     background: #f4ecd8;
14|     overflow: hidden;
15|     touch-action: none;
16|   }
17|   canvas {
18|     display: block;
19|     width: 100vw;
20|     height: 100dvh;
21|     touch-action: none;
22|   }
23| </style>
24| </head>
25| <body>
26| <canvas id="game"></canvas>
27| <script>
28| // ---- Bridge helper (verbatim) ----
29| const CARTRIDGE = {
30|   send(type, payload = {}) {
31|     window.parent.postMessage(
32|       { source: "cartridge", v: 1, type, payload },
33|       "*",
34|     );
35|   },
36| };
37| </script>
38| <script>
39| (function () {
40|   const canvas = document.getElementById("game");
41|   const ctx = canvas.getContext("2d");
42| 
43|   let dpr = Math.max(1, window.devicePixelRatio || 1);
44|   let W = 0, H = 0;
45| 
46|   function resize() {
47|     W = window.innerWidth;
48|     H = window.innerHeight;
49|     canvas.width = Math.floor(W * dpr);
50|     canvas.height = Math.floor(H * dpr);
51|     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
52|   }
53|   window.addEventListener("resize", resize);
54|   resize();
55| 
56|   // ---- seeded jitter helper for paper-cut look ----
57|   function seededRandom(seed) {
58|     let s = seed % 2147483647;
59|     if (s <= 0) s += 2147483646;
60|     return function () {
61|       s = (s * 16807) % 2147483647;
62|       return (s - 1) / 2147483646;
63|     };
64|   }
65|   const jitterRand = seededRandom(12345);
66|   function jitter(v, amt) {
67|     return v + (jitterRand() - 0.5) * amt;
68|   }
69| 
70|   const PALETTE = {
71|     background: "#f4ecd8",
72|     layer: "#e07a5f",
73|     accent: "#3d405b",
74|     highlight: "#81b29a",
75|   };
76| 
77|   // ---- game state ----
78|   let last = 0,
79|     running = false,
80|     paused = false,
81|     started = false,
82|     score = 0;
83| 
84|   let kiteY = 0, kiteVy = 0;
85|   const kiteX = 0.28; // fraction of width
86|   const gravity = 620;
87|   const flapImpulse = -300;
88|   const maxFall = 480;
89| 
90|   let scrollSpeed = 160;
91|   const baseSpeed = 160;
92|   let elapsed = 0;
93| 
94|   let obstacles = []; // chimneys {x, gapY, gapH, w, passed}
95|   let ribbons = []; // {x, y, r, taken}
96| 
97|   let clouds = [];
98| 
99|   let tapHintPulse = 0;
100| 
101|   function initClouds() {
102|     clouds = [];
103|     for (let i = 0; i < 5; i++) {
104|       clouds.push({
105|         x: Math.random() * 1,
106|         y: 0.05 + Math.random() * 0.35,
107|         s: 0.5 + Math.random() * 0.8,
108|         speed: 0.02 + Math.random() * 0.03,
109|       });
110|     }
111|   }
112|   initClouds();
113| 
114|   function resetState() {
115|     running = false;
116|     started = false;
117|     paused = false;
118|     score = 0;
119|     kiteY = H * 0.5;
120|     kiteVy = 0;
121|     scrollSpeed = baseSpeed;
122|     elapsed = 0;
123|     obstacles = [];
124|     ribbons = [];
125|     spawnInitialObstacle();
126|   }
127| 
128|   function spawnInitialObstacle() {
129|     // Fairness: keep opening lane clear, first hazard well ahead
130|     obstacles.push(makeObstacle(W + W * 0.9));
131|   }
132| 
133|   function makeObstacle(x) {
134|     const gapH = Math.max(H * 0.28, 170);
135|     const margin = H * 0.12;
136|     const gapY = margin + Math.random() * (H - gapH - margin * 2);
137|     return {
138|       x: x,
139|       w: 62,
140|       gapY: gapY,
141|       gapH: gapH,
142|       passed: false,
143|     };
144|   }
145| 
146|   function maybeSpawnRibbon(obstacleX, gapY, gapH) {
147|     if (Math.random() < 0.85) {
148|       ribbons.push({
149|         x: obstacleX + 120 + Math.random() * 60,
150|         y: gapY + gapH / 2 + (Math.random() - 0.5) * gapH * 0.3,
151|         r: 14,
152|         taken: false,
153|       });
154|     }
155|   }
156| 
157|   function backToTitle() {
158|     resetState();
159|   }
160| 
161|   function act() {
162|     kiteVy = flapImpulse;
163|   }
164| 
165|   // ---- input ----
166|   canvas.style.touchAction = "none";
167|   canvas.addEventListener("pointerdown", (event) => {
168|     event.preventDefault();
169|     if (paused) return;
170|     if (!running) {
171|       running = true;
172|       started = true;
173|       CARTRIDGE.send("start");
174|       return;
175|     }
176|     act();
177|   });
178| 
179|   // ---- host messages ----
180|   window.addEventListener("message", (event) => {
181|     const data = event.data;
182|     if (!data || data.source !== "cartridge-host") return;
183|     if (data.type === "pause") paused = true;
184|     if (data.type === "resume") paused = false;
185|     if (data.type === "reset") backToTitle();
186|   });
187| 
188|   function advance(dt) {
189|     elapsed += dt;
190|     // ramp difficulty with speed over time
191|     scrollSpeed = baseSpeed + Math.min(elapsed * 4.5, 160);
192| 
193|     kiteVy += gravity * dt;
194|     if (kiteVy > maxFall) kiteVy = maxFall;
195|     kiteY += kiteVy * dt;
196| 
197|     if (kiteY < 20) {
198|       kiteY = 20;
199|       kiteVy = 0;
200|     }
201|     if (kiteY > H - 20) {
202|       kiteY = H - 20;
203|       // still allowed to fly, but let's not force crash on floor; kite bumps back
204|       kiteVy = 0;
205|     }
206| 
207|     for (const o of obstacles) {
208|       o.x -= scrollSpeed * dt;
209|     }
210|     for (const r of ribbons) {
211|       r.x -= scrollSpeed * dt;
212|     }
213| 
214|     // spawn new obstacles
215|     if (obstacles.length === 0 || obstacles[obstacles.length - 1].x < W - 320) {
216|       const newX = (obstacles.length ? obstacles[obstacles.length - 1].x : W) + 320 + Math.random() * 100;
217|       const o = makeObstacle(newX);
218|       obstacles.push(o);
219|       maybeSpawnRibbon(o.x, o.gapY, o.gapH);
220|     }
221| 
222|     // remove offscreen
223|     obstacles = obstacles.filter((o) => o.x + o.w > -20);
224|     ribbons = ribbons.filter((r) => r.x > -40);
225| 
226|     // score for passing obstacles
227|     const px = W * kiteX;
228|     for (const o of obstacles) {
229|       if (!o.passed && o.x + o.w < px) {
230|         o.passed = true;
231|         score += 1;
232|         CARTRIDGE.send("score", { value: score });
233|       }
234|     }
235| 
236|     // ribbon collection
237|     for (const r of ribbons) {
238|       if (r.taken) continue;
239|       const dx = r.x - px;
240|       const dy = r.y - kiteY;
241|       const dist = Math.sqrt(dx * dx + dy * dy);
242|       if (dist < r.r + 16) {
243|         r.taken = true;
244|         score += 3;
245|         CARTRIDGE.send("score", { value: score });
246|       }
247|     }
248|     ribbons = ribbons.filter((r) => !r.taken);
249| 
250|     // clouds drift
251|     for (const c of clouds) {
252|       c.x -= c.speed * dt * 0.6;
253|       if (c.x < -0.2) c.x = 1.2;
254|     }
255|   }
256| 
257|   function collide() {
258|     const px = W * kiteX;
259|     const kiteR = 16;
260|     for (const o of obstacles) {
261|       if (px + kiteR > o.x && px - kiteR < o.x + o.w) {
262|         if (kiteY - kiteR < o.gapY || kiteY + kiteR > o.gapY + o.gapH) {
263|           crash();
264|           return;
265|         }
266|       }
267|     }
268|   }
269| 
270|   function crash() {
271|     running = false;
272|     CARTRIDGE.send("end", { reason: "lose", value: score });
273|   }
274| 
275|   // ---- drawing (paper-cut style) ----
276|   function roundedRectPath(x, y, w, h, r, jitterAmt) {
277|     ctx.beginPath();
278|     const pts = [
279|       [x + r, y],
280|       [x + w - r, y],
281|       [x + w, y + r],
282|       [x + w, y + h - r],
283|       [x + w - r, y + h],
284|       [x + r, y + h],
285|       [x, y + h - r],
286|       [x, y + r],
287|     ];
288|     ctx.moveTo(jitter(pts[0][0], jitterAmt), jitter(pts[0][1], jitterAmt));
289|     ctx.arcTo(jitter(x + w, jitterAmt), jitter(y, jitterAmt), jitter(x + w, jitterAmt), jitter(y + h, jitterAmt), r);
290|     ctx.arcTo(jitter(x + w, jitterAmt), jitter(y + h, jitterAmt), jitter(x, jitterAmt), jitter(y + h, jitterAmt), r);
291|     ctx.arcTo(jitter(x, jitterAmt), jitter(y + h, jitterAmt), jitter(x, jitterAmt), jitter(y, jitterAmt), r);
292|     ctx.arcTo(jitter(x, jitterAmt), jitter(y, jitterAmt), jitter(x + w, jitterAmt), jitter(y, jitterAmt), r);
293|     ctx.closePath();
294|   }
295| 
296|   function drawBackground() {
297|     ctx.fillStyle = PALETTE.background;
298|     ctx.fillRect(0, 0, W, H);
299| 
300|     // clouds - soft paper shapes
301|     ctx.save();
302|     ctx.shadowColor = "rgba(61,64,91,0.15)";
303|     ctx.shadowBlur = 6;
304|     ctx.shadowOffsetY = 2;
305|     for (const c of clouds) {
306|       const cx = c.x * W;
307|       const cy = c.y * H;
308|       const s = c.s * 40;
309|       ctx.fillStyle = "#ffffff";
310|       ctx.beginPath();
311|       ctx.ellipse(jitter(cx, 2), jitter(cy, 2), s, s * 0.6, 0, 0, Math.PI * 2);
312|       ctx.ellipse(jitter(cx + s * 0.7, 2), jitter(cy + 4, 2), s * 0.7, s * 0.45, 0, 0, Math.PI * 2);
313|       ctx.ellipse(jitter(cx - s * 0.6, 2), jitter(cy + 6, 2), s * 0.6, s * 0.4, 0, 0, Math.PI * 2);
314|       ctx.fill();
315|     }
316|     ctx.restore();
317|   }
318| 
319|   function drawObstacle(o) {
320|     ctx.save();
321|     ctx.shadowColor = "rgba(61,64,91,0.25)";
322|     ctx.shadowBlur = 6;
323|     ctx.shadowOffsetY = 3;
324|     ctx.fillStyle = PALETTE.layer;
325| 
326|     // top chimney
327|     roundedRectPath(o.x, 0, o.w, o.gapY, 6, 1.5);
328|     ctx.fill();
329| 
330|     // bottom chimney
331|     roundedRectPath(o.x, o.gapY + o.gapH, o.w, H - (o.gapY + o.gapH), 6, 1.5);
332|     ctx.fill();
333| 
334|     ctx.restore();
335| 
336|     // accent cap details
337|     ctx.fillStyle = PALETTE.accent;
338|     ctx.fillRect(jitter(o.x - 4, 1), jitter(o.gapY - 14, 1), o.w + 8, 14);
339|     ctx.fillRect(jitter(o.x - 4, 1), jitter(o.gapY + o.gapH, 1), o.w + 8, 14);
340|   }
341| 
342|   function drawRibbon(r) {
343|     ctx.save();
344|     ctx.shadowColor = "rgba(61,64,91,0.2)";
345|     ctx.shadowBlur = 5;
346|     ctx.shadowOffsetY = 2;
347|     ctx.fillStyle = PALETTE.highlight;
348|     ctx.beginPath();
349|     ctx.moveTo(jitter(r.x, 1.5), jitter(r.y - r.r, 1.5));
350|     ctx.lineTo(jitter(r.x + r.r, 1.5), jitter(r.y, 1.5));
351|     ctx.lineTo(jitter(r.x, 1.5), jitter(r.y + r.r, 1.5));
352|     ctx.lineTo(jitter(r.x - r.r, 1.5), jitter(r.y, 1.5));
353|     ctx.closePath();
354|     ctx.fill();
355|     ctx.restore();
356| 
357|     // little tail
358|     ctx.strokeStyle = PALETTE.highlight;
359|     ctx.lineWidth = 3;
360|     ctx.beginPath();
361|     ctx.moveTo(r.x, r.y + r.r);
362|     ctx.lineTo(r.x - 4, r.y + r.r + 10);
363|     ctx.moveTo(r.x, r.y + r.r);
364|     ctx.lineTo(r.x + 4, r.y + r.r + 10);
365|     ctx.stroke();
366|   }
367| 
368|   function drawKite(x, y) {
369|     ctx.save();
370|     ctx.shadowColor = "rgba(61,64,91,0.3)";
371|     ctx.shadowBlur = 6;
372|     ctx.shadowOffsetY = 3;
373| 
374|     const angle = Math.max(-0.5, Math.min(0.5, kiteVy / 400));
375| 
376|     ctx.translate(x, y);
377|     ctx.rotate(angle);
378| 
379|     // kite body: diamond shape stacked layers
380|     ctx.fillStyle = PALETTE.accent;
381|     ctx.beginPath();
382|     ctx.moveTo(jitter(0, 1.5), jitter(-26, 1.5));
383|     ctx.lineTo(jitter(20, 1.5), jitter(0, 1.5));
384|     ctx.lineTo(jitter(0, 1.5), jitter(30, 1.5));
385|     ctx.lineTo(jitter(-20, 1.5), jitter(0, 1.5));
386|     ctx.closePath();
387|     ctx.fill();
388| 
389|     ctx.fillStyle = PALETTE.layer;
390|     ctx.beginPath();
391|     ctx.moveTo(jitter(0, 1.5), jitter(-20, 1.5));
392|     ctx.lineTo(jitter(14, 1.5), jitter(0, 1.5));
393|     ctx.lineTo(jitter(0, 1.5), jitter(22, 1.5));
394|     ctx.lineTo(jitter(-14, 1.5), jitter(0, 1.5));
395|     ctx.closePath();
396|     ctx.fill();
397| 
398|     ctx.restore();
399| 
400|     // tail ribbons
401|     ctx.strokeStyle = PALETTE.highlight;
402|     ctx.lineWidth = 3;
403|     ctx.beginPath();
404|     const tailWobble = Math.sin(elapsed * 6) * 6;
405|     ctx.moveTo(x, y + 28);
406|     ctx.quadraticCurveTo(x - 10 + tailWobble, y + 45, x - 4, y + 60);
407|     ctx.stroke();
408|   }
409| 
410|   function drawCard(text, subtext, y) {
411|     ctx.save();
412|     const cardW = Math.min(340, W * 0.8);
413|     const cardH = 120;
414|     const cx = W / 2 - cardW / 2;
415|     const cy = y - cardH / 2;
416|     ctx.shadowColor = "rgba(61,64,91,0.25)";
417|     ctx.shadowBlur = 6;
418|     ctx.shadowOffsetY = 3;
419|     ctx.fillStyle = "#ffffff";
420|     roundedRectPath(cx, cy, cardW, cardH, 14, 1.5);
421|     ctx.fill();
422|     ctx.restore();
423| 
424|     ctx.fillStyle = PALETTE.accent;
425|     ctx.font = "bold 26px system-ui, sans-serif";
426|     ctx.textAlign = "center";
427|     ctx.textBaseline = "middle";
428|     ctx.fillText(text, W / 2, cy + 42);
429| 
430|     ctx.font = "16px system-ui, sans-serif";
431|     ctx.fillText(subtext, W / 2, cy + 78);
432|   }
433| 
434|   function drawScoreBadge() {
435|     ctx.save();
436|     const w = 90, h = 40;
437|     ctx.shadowColor = "rgba(61,64,91,0.2)";
438|     ctx.shadowBlur = 5;
439|     ctx.shadowOffsetY = 2;
440|     ctx.fillStyle = "#ffffff";
441|     roundedRectPath(16, 16, w, h, 10, 1);
442|     ctx.fill();
443|     ctx.restore();
444| 
445|     ctx.fillStyle = PALETTE.accent;
446|     ctx.font = "bold 20px system-ui, sans-serif";
447|     ctx.textAlign = "center";
448|     ctx.textBaseline = "middle";
449|     ctx.fillText("★ " + score, 16 + w / 2, 16 + h / 2 + 1);
450|   }
451| 
452|   function draw() {
453|     drawBackground();
454| 
455|     if (!started) {
456|       // idle prompt, kite gently bobbing so it never looks frozen
457|       const bob = Math.sin(elapsed * 2) * 10;
458|       drawKite(W * kiteX, H * 0.5 + bob);
459|       tapHintPulse += 0.05;
460|       const alpha = 0.6 + 0.4 * Math.sin(tapHintPulse * 2);
461|       ctx.globalAlpha = alpha;
462|       drawCard("Kite on the Wind", "Tap to begin", H * 0.72);
463|       ctx.globalAlpha = 1;
464|       ctx.fillStyle = PALETTE.accent;
465|       ctx.font = "bold 30px system-ui, sans-serif";
466|       ctx.textAlign = "center";
467|       return;
468|     }
469| 
470|     for (const o of obstacles) drawObstacle(o);
471|     for (const r of ribbons) drawRibbon(r);
472|     drawKite(W * kiteX, kiteY);
473|     drawScoreBadge();
474| 
475|     if (!running) {
476|       drawCard("Flight Over", "Ribbons: " + score + " — tap to fly again", H * 0.42);
477|     }
478| 
479|     if (paused) {
480|       drawCard("Paused", "Waiting...", H * 0.5);
481|     }
482|   }
483| 
484|   // ---- restart after crash via tap ----
485|   canvas.addEventListener("pointerdown", (event) => {
486|     if (paused) return;
487|     if (started && !running) {
488|       // small delay handled naturally: just reset and immediately treat as new start
489|       resetState();
490|       running = true;
491|       started = true;
492|       CARTRIDGE.send("start");
493|     }
494|   });
495| 
496|   function frame(now) {
497|     const dt = Math.min((now - last) / 1000, 0.05);
498|     last = now;
499|     if (running && !paused) {
500|       advance(dt);
501|       collide();
502|     } else if (!started) {
503|       elapsed += dt;
504|       for (const c of clouds) {
505|         c.x -= c.speed * dt * 0.6;
506|         if (c.x < -0.2) c.x = 1.2;
507|       }
508|     }
509|     draw();
510|     requestAnimationFrame(frame);
511|   }
512| 
513|   // init
514|   resetState();
515|   requestAnimationFrame((t) => {
516|     last = t;
517|     draw();
518|     CARTRIDGE.send("boot", { title: "Kite on the Wind", gameType: "arcade-run", lang: "en" });
519|     requestAnimationFrame(frame);
520|   });
521| })();
522| </script>
523| </body>
524| </html>
525|

